import { BlockIframeData } from './BlockIframeData';
/**
 * A partial description of a story
 */
type StoryMetadata = {
    id: number;
};
/**
 * A partial description of block content
 */
type BlockContent = {
    _uid: string;
};
/**
 * A partial description of a component
 */
type Component = {
    name: string;
    display_name: string;
};
/**
 * The event that is sent from Storyblok's Visual Editor to the embedded application via `Window.postMessage`.
 * The type is a discriminated union where the `action` property is the discriminator.
 */
export type BridgeEvent = InputBridgeEvent | CustomEventBridgeEvent | HoverComponentBridgeEvent | HighlightComponentBridgeEvent | ChangeBridgeEvent | PublishedBridgeEvent | UnpublishedBridgeEvent | DuplicatedBlockBridgeEvent | MovedBlockBridgeEvent | AddedBlockBridgeEvent | EnterComponentBridgeEvent | EnterEditModeBridgeEvent | PingBackBridgeEvent | EditedBlockBridgeEvent;
export type InputBridgeEvent<TStory = StoryMetadata> = {
    action: 'input';
    story: TStory;
};
export type CustomEventBridgeEvent = {
    action: 'customEvent';
    event: 'start-sync';
};
export type HoverComponentBridgeEvent = {
    action: 'hoverComponent';
    componentId: string;
    storyId: number;
};
export type HighlightComponentBridgeEvent = {
    action: 'highlightComponent';
    componentIds: string[];
    componentId: string;
    storyId: StoryMetadata['id'];
};
export type ChangeBridgeEvent = {
    reload: true;
    action: 'change';
    slug: string;
    storyId: StoryMetadata['id'];
    slugChanged?: boolean;
};
export type PublishedBridgeEvent = {
    action: 'published';
    slug: string;
    storyId: StoryMetadata['id'];
    slugChanged: boolean;
};
export type UnpublishedBridgeEvent = {
    action: 'unpublished';
    slug: string;
    storyId: StoryMetadata['id'];
};
export type DuplicatedBlockBridgeEvent = {
    action: 'duplicatedBlock';
    blockId: BlockContent['_uid'];
};
export type MovedBlockBridgeEvent = {
    action: 'movedBlock';
    blockId: BlockContent['_uid'];
};
export type AddedBlockBridgeEvent = {
    action: 'addedBlock';
    blockId: BlockContent['_uid'];
};
export type EnterComponentBridgeEvent = {
    action: 'enterComponent';
    componentId: string;
    storyId: StoryMetadata['id'];
    breadcrumbs: unknown[];
    blok: BlockIframeData;
    canAddBlocks?: boolean;
    canMoveForward?: boolean;
    canMoveBackward?: boolean;
    canDeleteBlocks?: boolean;
};
export type EnterEditModeBridgeEvent = {
    reload: true;
    action: 'enterEditmode';
    blockId: BlockContent['_uid'];
    storyId: StoryMetadata['id'];
    componentNames: Record<Component['name'], Component['display_name']>;
    appVersion: 'v2' | 'v1';
};
export type PingBackBridgeEvent = {
    action: 'pingBack';
};
export type EditedBlockBridgeEvent = {
    action: 'editedBlok';
    breadcrumbs: unknown[];
    blok: BlockIframeData;
    canAddBlocks?: boolean;
    canMoveForward?: boolean;
    canMoveBackward?: boolean;
    canDeleteBlocks?: boolean;
};
export {};
